using System.Text;

using Xunit;

namespace Paramore.Brighter.Kafka.Tests.MessagingGateway.Consumer.Reactor;

/// <summary>
/// With no dead-letter queue or invalid-message channel, a rejected message is acknowledged: it
/// never comes back, and the message behind it still arrives. Messages are identified by id, never
/// by arrival order.
/// </summary>
[Trait("Category", "Kafka")]
[Collection("Kafka")]
public class WhenRejectingMessageWithNoChannelsConfiguredShouldAcknowledgeAndLog : IDisposable
{
    private readonly IAmAMessageGatewayReactorProvider _messageGatewayProvider;
    private readonly IAmAMessageBuilder _messageBuilder;
    private readonly IAmAMessageAssertion _messageAssertion;

    private List<Message> _sentMessages = [];

    private Paramore.Brighter.MessagingGateway.Kafka.KafkaSubscription? _subscription;
    private Paramore.Brighter.MessagingGateway.Kafka.KafkaPublication? _publication;

    private IAmAMessageProducerSync? _producer = null;
    private IAmAChannelSync? _channel = null;

    public WhenRejectingMessageWithNoChannelsConfiguredShouldAcknowledgeAndLog()
    {
        _messageGatewayProvider = new Paramore.Brighter.Kafka.Tests.MessagingGateway.KafkaConsumerMessageGatewayProvider();
        _messageBuilder = new DefaultMessageBuilder();
        _messageAssertion = new KafkaMessageAssertion();
    }

    public void Dispose()
    {
        _messageGatewayProvider.CleanUp(_producer, _channel, _sentMessages);
    }

    [Fact]
    public void When_rejecting_message_with_no_channels_configured_should_acknowledge_and_log()
    {
        // Arrange
        _publication = _messageGatewayProvider.CreatePublication(_messageGatewayProvider.GetOrCreateRoutingKey());
        _subscription = _messageGatewayProvider.CreateSubscription(_publication.Topic!,
            _messageGatewayProvider.GetOrCreateChannelName(),
            OnMissingChannel.Create);

        _producer = _messageGatewayProvider.CreateProducer(_publication);
        _channel = _messageGatewayProvider.CreateChannel(_subscription);

        var firstSent = _messageBuilder.SetTopic(_publication.Topic!)
            .SetMessageId(Id.Random())
            .SetBody(Encoding.UTF8.GetBytes(Id.Random().ToString()))
            .Build();
        _sentMessages.Add(firstSent);

        var secondSent = _messageBuilder.SetTopic(_publication.Topic!)
            .SetMessageId(Id.Random())
            .SetBody(Encoding.UTF8.GetBytes(Id.Random().ToString()))
            .Build();
        _sentMessages.Add(secondSent);

        _producer.Send(firstSent);
        _producer.Send(secondSent);

        // Act
        var received = _channel.Receive(TimeSpan.FromMilliseconds(15000));
        Assert.NotEqual(MessageType.MT_NONE, received.Header.MessageType);

        var rejectedMessage = _sentMessages.Single(m => m.Header.MessageId == received.Header.MessageId);
        var theOtherMessage = _sentMessages.Single(m => m.Header.MessageId != rejectedMessage.Header.MessageId);

        var rejected = _channel.Reject(received, new MessageRejectionReason(RejectionReason.DeliveryError, "Test rejection with no channels configured"));

        // Assert
        Assert.True(rejected, "Reject should return true when no channels are configured");

        // Assert
        var receivedOther = new Message();
        var stopwatch = Stopwatch.StartNew();
        while (stopwatch.Elapsed < TimeSpan.FromSeconds(30))
        {
            var next = _channel.Receive(TimeSpan.FromMilliseconds(500));
            if (next.Header.MessageType == MessageType.MT_NONE)
            {
                continue;
            }

            Assert.NotEqual(rejectedMessage.Header.MessageId, next.Header.MessageId);

            receivedOther = next;
            break;
        }

        Assert.NotEqual(MessageType.MT_NONE, receivedOther.Header.MessageType);
        _messageAssertion.Assert(theOtherMessage, receivedOther);
    }
